    out = [row[:] for row in grid]
    # Every 2 on a colored rectangular field marks a 3x3 patch. The field
    # is the contiguous horizontal 3-run on its row; this avoids unrelated
    # nearby 2s outside the field.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            # Determine whether this marker belongs to a row of the 3 field
            # by checking a 3 immediately to left/right or above/below.
            if not any(0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 3
                       for rr, cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))):
